Rails.application.routes.draw do
  get "up" => "rails/health#show", as: :rails_health_check
  root to: redirect("/moderate", status: 302)

  get "/play/:code", to: "play#show", as: :play
  post "/play/:code", to: "play#join"
  get "/play/:code/state", to: "play#state", as: :play_state
  post "/play/:code/answer", to: "play#answer", as: :play_answer
  post "/play/:code/presence", to: "play#presence", as: :play_presence

  namespace :moderate do
    get "/", to: "quizzes#index", as: :root
    resource :quiz_import, only: [:new, :create]
    resources :quizzes, except: :index do
      get :export, on: :member
      get :preview, on: :member
      resources :games, only: [:create, :show], shallow: true do
        get :state, on: :member
        post :advance, on: :member
      end
      resources :questions, except: [:index, :show] do
        member do
          patch :active, action: :set_active
          patch :move
        end
      end
    end
  end
end
